  "Science JHS1 s4 ss3 - Forces and Energy": PracticeModel(
    audioPath: '',
    questions: [
      PracticeQuestion(
        scenario: "QUESTION 1 (BECE 2010 Q2)\n\n"
            "(a) State the name of the energy possessed by moving water.\n\n"
